from build123d import *

# ---- Overall envelope (HELIOS-2970) ----
plate_w = 80.0
plate_h = 58.0
plate_t = 4.9
corner_r = 2.9            # 4x R2.9 corner fillets

# ---- Main grid: 12x D18.3 THRU (4x3), pitch 19.3 ----
main_d   = 18.3
cols_x   = 4
rows_y   = 3
pitch    = 19.3

x0 = -(cols_x - 1) * pitch / 2   # -28.95
y0 = -(rows_y - 1) * pitch / 2   # -19.30

# ---- Base plate ----
plate = Box(plate_w, plate_h, plate_t)
plate = fillet(plate.edges().filter_by(Axis.Z), corner_r)

def drill(shape, x, y, dia):
    return shape - Pos(x, y, 0) * Cylinder(dia / 2, plate_t + 2)

# ---- Pre-build 3D slot solids (extruded from 2D sketches) ----
short_slot = extrude(SlotOverall(9.5, 7.8), amount=(plate_t + 2) / 2, both=True)
long_slot  = extrude(SlotOverall(28.8, 7.8), amount=(plate_t + 2) / 2, both=True)

# ---- 12x D18.3 main holes (4x3) ----
for i in range(cols_x):
    for j in range(rows_y):
        plate = drill(plate, x0 + i * pitch, y0 + j * pitch, main_d)

# ---- 6x D5.8 THRU (3x2) between main columns, at top/bottom rows ----
for i in range(3):
    for y in (y0, y0 + 2 * pitch):
        plate = drill(plate, x0 + (i + 0.5) * pitch, y, 5.8)

# ---- 6x D3.9 THRU (2x3) at outer columns, mid rows ----
for x in (x0 - 0.5 * pitch, x0 + 3.5 * pitch):
    for j in range(3):
        plate = drill(plate, x, y0 + j * pitch, 3.9)

# ---- 8x D2.9 THRU at periphery nodes ----
for x in (x0 + 0.5 * pitch, x0 + 2.5 * pitch):
    for y in (y0 - 0.5 * pitch, y0 + 2.5 * pitch):
        plate = drill(plate, x, y, 2.9)
for x in (x0 - 0.5 * pitch, x0 + 3.5 * pitch):
    for y in (y0 + 0.5 * pitch, y0 + 1.5 * pitch):
        plate = drill(plate, x, y, 2.9)

# ---- 6x SLOT 7.8 x 9.5 (short slots) ----
for x in (x0 + 0.5 * pitch, x0 + 1.5 * pitch, x0 + 2.5 * pitch):
    for y in (y0 + 0.5 * pitch, y0 + 1.5 * pitch):
        plate -= Pos(x, y, 0) * short_slot

# ---- 4x SLOT 7.8 x 28.8 (long slots, Y-oriented) ----
for x in (x0 - 0.5 * pitch, x0 + 3.5 * pitch):
    for y in (y0 + 0.5 * pitch, y0 + 1.5 * pitch):
        plate -= Pos(x, y, 0) * Rot(0, 0, 90) * long_slot

part = plate
part.name = "plate_HELIOS_2970"
export_step(part, "output.step")
